#!/usr/bin/env bash
# v2.5 個別支援計画の写真OCR - Docker既存環境の療育アプリのみ更新
set -Eeuo pipefail
umask 077
EXPECTED_SHA256="7258bf45025740b0b7f50201076d047c80c4ca7d57bec5ec63dffcaffddcd684"
usage() {
cat <<'HELP'
使い方:
  bash update-ryoiku-v2.5.sh --verify       # 内蔵ファイルを検証
  sudo bash update-ryoiku-v2.5.sh --check   # 対象のDockerを検出（変更なし）
  sudo bash update-ryoiku-v2.5.sh --apply   # バックアップして療育アプリのみ更新

v2.4からの更新専用。バックアップを外部にも保管してから更新してください。
8080以外の既存サービス、Tailscale、Cloudflare Tunnelには触れません。
HELP
}
fail(){ printf 'エラー: %s\n' "$*" >&2; exit 1; }
mode="${1:---check}"
case "$mode" in --help|-h) usage;exit 0;; --verify|--check|--apply) ;; *) usage >&2;exit 2;; esac
for c in base64 sha256sum unzip mktemp tar; do
 command -v "$c" >/dev/null 2>&1 || fail "$c がありません。";
done
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
base64 -d >"$TMP/app.zip" <<'RYOIKU_B64'
