RYOIKU_B64
actual="$(sha256sum "$TMP/app.zip" | awk '{print $1}')"
[[ "$actual" == "$EXPECTED_SHA256" ]] || fail '更新ファイルのSHA256が一致しません。'
unzip -tqq "$TMP/app.zip" || fail 'ZIPの整合性確認に失敗しました。'
if [[ "$mode" == '--verify' ]]; then echo "OK: v2.5検証完了 SHA256=$actual";exit 0;fi
[[ "$EUID" -eq 0 ]] || fail '実際のDocker操作にはsudoが必要です。'
for c in docker curl; do command -v "$c" >/dev/null 2>&1 || fail "$c がありません。"; done
docker compose version >/dev/null || fail 'Docker Composeが利用できません。'
docker info >/dev/null || fail 'Dockerに接続できません。'
container='minecraft-ryoiku-web'
docker container inspect "$container" >/dev/null 2>&1 || fail "コンテナ ${container} が見つかりません。"
service="$(docker inspect -f '{{ index .Config.Labels "com.docker.compose.service" }}' "$container")"
[[ "$service" == 'ryoiku' ]] || fail "想定外のComposeサービス: $service"
DEST="$(docker inspect -f '{{ index .Config.Labels "com.docker.compose.project.working_dir" }}' "$container")"
[[ -n "$DEST" && "$DEST" == /* && -f "$DEST/compose.yml" && -f "$DEST/.env" && -d "$DEST/data" ]] || fail '既存の設定またはデータが見つかりません。上書きを中止します。'
printf '\n対象コンテナ: %s\n実際の保存先: %s\n' "$container" "$DEST"
docker compose -f "$DEST/compose.yml" --project-directory "$DEST" ps ryoiku
if [[ "$mode" == '--check' ]]; then echo '事前確認のみ完了しました。何も変更していません。';exit 0;fi
unzip -q "$TMP/app.zip" -d "$TMP"
SOURCE="$TMP/minecraft_ryoiku_web"
for f in app.py ocr_import.py storage.py templates/support_form.html Dockerfile requirements.txt compose.yml; do
  [[ -f "$SOURCE/$f" ]] || fail "更新用ファイルがありません: $f"
done
[[ ! -e "$SOURCE/.env" && ! -e "$SOURCE/data" ]] || fail 'ZIPに個人情報または設定ファイルが含まれています。'
if ! cmp -s "$SOURCE/compose.yml" "$DEST/compose.yml"; then
  fail '既存compose.ymlに変更があります。データと他サービスを守るため上書きを中止します。'
fi
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/var/backups/ryoiku-curriculum/${STAMP}"
mkdir -p "$BACKUP"
chmod 700 /var/backups/ryoiku-curriculum "$BACKUP"
cd "$DEST"
echo '療育アプリを一時停止します。他のDockerコンテナは変更しません。'
docker compose stop ryoiku
printf '個人データ・秘密鍵・プログラムをバックアップ: %s\n' "$BACKUP"
tar -czf "$BACKUP/data-and-env.tar.gz" .env data || fail 'データバックアップ失敗。既存アプリは停止中です。'
tar --exclude='./data' --exclude='./.env' -czf "$BACKUP/code-before-update.tar.gz" . || fail 'プログラムバックアップ失敗。既存アプリは停止中です。'
chmod 600 "$BACKUP"/*.gz
# 個人情報・暗号化キーは一切上書きしない。
cp -a "$SOURCE/." "$DEST/"
echo '新しいTesseract日本語OCR入りのDockerイメージをビルドします。'
docker compose build ryoiku
docker compose up -d --no-deps ryoiku
success=0
for _ in $(seq 1 20); do
  response="$(curl -sS -o /dev/null -w '%{http_code}' --max-time 3 http://127.0.0.1:8080/login 2>/dev/null || true)"
  if [[ "$response" == '200' || "$response" == '303' ]]; then success=1;break;fi
  sleep 2
done
docker compose ps ryoiku
if [[ "$success" != 1 ]]; then
 echo "HTTP接続できません。ログ確認: cd '$DEST' && sudo docker compose logs --tail=100 ryoiku"
 echo "復元用バックアップ: $BACKUP";exit 3
fi
printf '\nOK: 療育システムv2.5更新完了。保存先: %s\nバックアップ: %s\n' "$DEST" "$BACKUP"
echo 'WebUIで 利用者→個別支援計画を入力・更新→写真から読み取る を開いてください。'
